import java.util.Scanner;

public class Main {
    static final int mod = 1000000007;

    static int add(int a, int b) {
        a += b;
        if (a >= mod) a -= mod;
        return a;
    }

    static int mult(int a, int b) {
        long t = 1L * a * b;
        if (t >= mod) t %= mod;
        return (int) t;
    }

    static class Matrix {
        int[][] dat;
        int N, M;

        public Matrix(int N, int M) {
            this.N = N;
            this.M = M;
            dat = new int[N][M];
        }

        void init() {
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < M; j++) {
                    dat[i][j] = 0;
                }
            }
        }

        void iden() {
            init();
            int min = Math.min(N, M);
            for (int i = 0; i < min; i++) {
                dat[i][i] = 1;
            }
        }

        Matrix trans() {
            Matrix out = new Matrix(M, N);
            for (int i = 0; i < M; i++) {
                for (int j = 0; j < N; j++) {
                    out.dat[i][j] = dat[j][i];
                }
            }
            return out;
        }

        int[] getRow(int x) {
            return dat[x];
        }

        int[] getColumn(int x) {
            int[] col = new int[N];
            for (int i = 0; i < N; i++) {
                col[i] = dat[i][x];
            }
            return col;
        }

        Matrix add(Matrix a) {
            Matrix out = new Matrix(N, M);
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < M; j++) {
                    out.dat[i][j] = add(dat[i][j], a.dat[i][j]);
                }
            }
            return out;
        }

        Matrix multiplyByScalar(int x) {
            Matrix out = new Matrix(N, M);
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < M; j++) {
                    out.dat[i][j] = mult(dat[i][j], x);
                }
            }
            return out;
        }

        static Matrix multiply(Matrix a, Matrix b) {
            Matrix out = new Matrix(a.N, b.M);
            out.init();
            for (int i = 0; i < a.N; i++) {
                for (int j = 0; j < a.M; j++) {
                    if (a.dat[i][j] != 0) {
                        for (int k = 0; k < b.M; k++) {
                            if (b.dat[j][k] != 0) {
                                out.dat[i][k] = add(out.dat[i][k], mult(a.dat[i][j], b.dat[j][k]));
                            }
                        }
                    }
                }
            }
            return out;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        int K = sc.nextInt();

        Matrix[][] A = new Matrix[65][35];
        Matrix[][] S = new Matrix[65][35];
        Matrix[][] P = new Matrix[65][35];

        for (int i = 0; i < 65; i++) {
            for (int j = 0; j < 35; j++) {
                A[i][j] = new Matrix(35, 35);
                S[i][j] = new Matrix(35, 35);
                P[i][j] = new Matrix(35, 35);
            }
        }

        for (int i = 0; i < K; i++) {
            A[0][i].iden();
            for (int j = 0; j <= K; j++) {
                A[0][i].dat[i][j] = 1;
            }
        }

        long len = K;
        int i = 1;
        while (len <= n) {
            S[i - 1][K - 1] = A[i - 1][K - 1];
            for (int j = K - 2; j >= 0; j--) {
                S[i - 1][j] = Matrix.multiply(A[i - 1][j], S[i - 1][j + 1]);
            }
            P[i - 1][0] = A[i - 1][0];
            for (int j = 1; j < K; j++) {
                P[i - 1][j] = Matrix.multiply(P[i - 1][j - 1], A[i - 1][j]);
            }
            A[i][0] = S[i - 1][0];
            for (int j = 1; j < K; j++) {
                A[i][j] = Matrix.multiply(S[i - 1][j], P[i - 1][j - 1]);
            }
            len *= K;
            i++;
        }

        int s = 0;
        int[] digit = new int[64];
        int digitCount = 0;
        long tempN = n;
        while (tempN > 0) {
            digit[digitCount++] = (int) (tempN % K);
            tempN /= K;
        }

        Matrix ans = new Matrix(35, 35);
        ans.iden();

        for (int idx = digitCount - 1; idx >= 0; idx--) {
            int d = digit[idx];
            for (int j = 0; j < d; j++) {
                ans = Matrix.multiply(ans, A[idx][(j + s) % K]);
            }
            s = (s + d) % K;
        }

        int res = 1;
        for (int i = 0; i < K; i++) {
            res = add(res, ans.dat[i][K]);
        }
        System.out.println(res);
        sc.close();
    }
}
